                post_hook={
                    "sql": "CREATE table if not exists PEESAFE_DB.MAPLEMONK.PEESAFE_DB_AMAZON_FACT_ITEMS ( Customer_id varchar,Shop_name varchar,Source varchar, order_id varchar, phone varchar, name varchar, email varchar, shipping_last_update_date varchar, sku varchar, product_id varchar, product_name varchar, currency varchar, city varchar, state varchar, order_status varchar, order_timestamp varchar, shipping_price float, quantity float, discount_before_tax float, tax float, total_Sales float, is_refund number(38,0), product_name_final varchar, product_category varchar, product_sub_category varchar,pincode varchar) ; create table if not exists PEESAFE_DB.MAPLEMONK.PEESAFE_DB_EasyEcom_FACT_ITEMS ( customer_id varchar, Shop_name varchar,marketplace varchar,Source varchar, order_id varchar, contact_num varchar, customer_name varchar, email varchar, shipping_last_update_date varchar, sku varchar, product_id varchar, productname varchar, currency varchar, city varchar, state varchar, order_status varchar, order_Date varchar, shipping_price float, suborder_quantity float, discount float, tax float, selling_price float, is_refund number(38,0), suborder_id variant, product_name_final varchar, product_category varchar, product_sub_category varchar, new_customer_flag varchar, shipping_status varchar, days_in_shipment varchar, awb varchar,Marketplace_LineItem_ID varchar, reference_code varchar,LAST_UPDATE_DATE date,PAYMENT_MODE varchar,COURIER varchar,MANIFEST_DATE date, DELIVERED_DATE date,mapped_product_name varchar,mapped_category varchar, mapped_sub_category varchar, warehouse_name varchar,pincode varchar,source_pincode varchar) ; create table if not exists PEESAFE_DB.MAPLEMONK.PEESAFE_DB_UNICOMMERCE_FACT_ITEMS ( order_id varchar ,order_Date date ,reference_code varchar ,name varchar ,email varchar ,city varchar ,state varchar ,phone varchar ,saleorderitemcode varchar ,sales_order_item_id varchar ,shippingpackagecode varchar ,SHIPPINGPACKAGESTATUS varchar ,shipping_status varchar ,order_status varchar ,Courier varchar ,Dispatch_Date date ,Delivered_date date ,Return_flag int ,Return_quantity int ,suborder_quantity int ,cancelled_quantity int ,selling_price float ,shipping_price float ,tax float ,discount float ,shipping_last_update_date date ,days_in_shipment float ,awb varchar ,marketplace varchar ,payment_method varchar ,PAYMENT_MODE varchar ,PRODUCT_ID varchar ,SKU varchar ,SKU_CODE varchar ,currency varchar ,NEW_CUSTOMER_FLAG varchar ,product_name varchar ,mapped_product_name varchar ,product_name_final varchar ,mapped_category varchar ,product_category varchar ,mapped_sub_category varchar ,product_sub_category varchar ,warehouse_name varchar ,pincode varchar) ; create table if not exists PEESAFE_DB.MAPLEMONK.PEESAFE_DB_SHOPIFY_FACT_ITEMS( SHOPIFY_CUSTOMER_ID_FINAL INT ,SHOPIFY_ACQUISITION_DATE DATE ,SHOPIFY_FIRST_COMPLETE_ORDER_DATE DATE ,MAPLE_MONK_ID_PHONE INT ,SHOP_NAME VARCHAR ,MARKETPLACE VARCHAR ,ORDER_ID VARCHAR ,ORDER_NAME VARCHAR ,CUSTOMER_ID INT ,NAME VARCHAR ,EMAIL VARCHAR ,PHONE VARCHAR ,TAGS VARCHAR ,LINE_ITEM_ID VARIANT ,SKU VARCHAR ,PRODUCT_ID VARCHAR ,CURRENCY VARCHAR ,IS_REFUND INT ,SHIPPING_CITY VARCHAR ,SHIPPING_STATE VARCHAR ,CITY VARCHAR ,STATE VARCHAR ,PRODUCT_NAME VARCHAR ,CATEGORY VARCHAR ,ORDER_STATUS VARCHAR ,ORDER_TIMESTAMP TIMESTAMP_NTZ(9) ,LINE_ITEM_SALES FLOAT ,QUANTITY FLOAT ,REFUND_QUANTITY INT ,REFUND_VALUE FLOAT ,TAX FLOAT ,TAX_RATE FLOAT ,DISCOUNT FLOAT ,DISCOUNT_BEFORE_TAX FLOAT ,GROSS_SALES_AFTER_TAX FLOAT ,GROSS_SALES_BEFORE_TAX FLOAT ,NET_SALES_BEFORE_TAX FLOAT ,SHIPPING_PRICE FLOAT ,TOTAL_SALES FLOAT ,SOURCE VARCHAR ,MOMENTS_COUNT INT ,DAYSTOCONVERT INT ,SHOPIFYQL_FIRSTVISIT_UTM_SOURCE VARCHAR ,SHOPIFYQL_MAPPED_SOURCE VARCHAR ,SHOPIFYQL_MAPPED_CHANNEL VARCHAR ,SHOPIFYQL_LAST_MOMENT_UTM_SOURCE VARCHAR ,SHOPIFYQL_LAST_VISIT_NON_UTM_SOURCE VARCHAR ,SHOPIFYQL_FIRSTVISIT_UTM_MEDIUM VARCHAR ,SHOPIFYQL_LAST_MOMENT_UTM_MEDIUM VARCHAR ,FINAL_UTM_CHANNEL VARCHAR ,FINAL_UTM_CAMPAIGN VARCHAR ,FINAL_UTM_SOURCE VARCHAR ,REFERRER_NAME VARCHAR ,CHECKOUT_MAPPED_SOURCE VARCHAR ,CHECKOUT_MAPPED_CHANNEL VARCHAR ,REFUND_DETAILS ARRAY ,AWB VARCHAR ,COURIER VARCHAR ,SHIPPING_STATUS VARCHAR ,SHIPPING_STATUS_UPDATE_DATE VARCHAR ,TRACKING_URL VARCHAR ,SHIPPING_CREATED_AT VARCHAR ,GATEWAY VARCHAR ,PAYMENT_MODE VARCHAR ,SKU_CODE VARCHAR ,COMMONSKUID VARCHAR ,PRODUCT_NAME_FINAL VARCHAR ,PRODUCT_CATEGORY VARCHAR ,PRODUCT_SUB_CATEGORY VARCHAR ,SHOPIFY_NEW_CUSTOMER_FLAG VARCHAR ,SHOPIFY_NEW_CUSTOMER_FLAG_MONTH VARCHAR ,SHOPIFY_ACQUISITION_PRODUCT VARCHAR ,SHOPIFY_ACQUISITION_CHANNEL VARCHAR ,SHOPIFY_ACQUISITION_SOURCE VARCHAR ,SHIPPING_TAX FLOAT ,SHIP_PROMOTION_DISCOUNT FLOAT ,GIFT_WRAP_PRICE FLOAT ,GIFT_WRAP_TAX FLOAT ,pincode varchar) ; CREATE or replace TABLE PEESAFE_DB.MAPLEMONK.shipment_status_mapping (SHIPPING_STATUS VARCHAR(16777216),Mapped_Status VARCHAR(16777216)); Insert into PEESAFE_DB.MAPLEMONK.shipment_status_mapping values (\'DELIVERED\',\'Delivered\') ,(\'CANCELLED\',\'Cancelled\') ,(\'DELIVERED TO ORIGIN\',\'Returned\') ,(\'SHIPMENT CREATED\',\'Shipment Created\') ,(\'RETURNED\',\'Returned\') ,(\'IN TRANSIT\',\'In Transit\') ,(\'DELIVERY DELAYED\',\'In Transit\') ,(\'DELIVERED TO ORIGIN\',\'RTO\') ,(\'CONFIRMED\',\'Open\') ,(\'IN_TRANSIT\',\'In Transit\') ,(\'RTO DELIVERED\',\'RTO\') ,(\'CANCELED\',\'Cancelled\') ,(\'RTO IN TRANSIT\',\'RTO\') ,(\'REACHED AT DESTINATION HUB\',\'In Transit\') ,(\'PICKED UP\',\'In Transit\') ,(\'UNDELIVERED-2ND ATTEMPT\',\'In Transit\') ,(\'RTO_OFD\',\'RTO\') ,(\'OUT FOR DELIVERY\',\'Out for delivery\') ,(\'RTO INITIATED\',\'RTO\') ,(\'PICKUP EXCEPTION\',\'Pickup Error\') ,(\'CANCELLATION REQUESTED\',\'Pickup Error\') ,(\'READY TO SHIP\',\'Ready to Ship\') ,(\'OUT_FOR_DELIVERY\',\'Out for delivery\') ,(\'SHIPPED\',\'In Transit\') ,(\'PICKUP RESCHEDULED\',\'Pickup Error\') ,(\'UNDELIVERED-3RD ATTEMPT\',\'In Transit\') ,(\'MISROUTED\',\'Misrouted\') ,(\'PICKUP SCHEDULED\',\'Pickup Error\') ,(\'UNDELIVERED-1ST ATTEMPT\',\'In Transit\') ,(\'Not Traceble\',\'Pickup Error\') ,(\'UNDELIVERED\',\'In Transit\') ,(\'LOST\',\'Lost\') ,(\'IN TRANSIT-EN-ROUTE\',\'In Transit\') ,(\'Indian Speed Post\',\'Indian Speed Post\') ,(\'Exception\',\'Exception\') ,(\'Shipment Booked\',\'Pickup Error\') ,(\'Assigned\',\'Assigned\') ,(\'Pending\',\'Pending\') ,(\'Printed\',\'Printed\') ,(\'IN TRANSIT-AT DESTINATION HUB\',\'In Transit\') ,(\'Upcoming\',\'Order Yet To sync\') ,(\'RTO-In Transit\',\'RTO\') ,(\'PICKUP ERROR\',\'Pickup Error\') ,(\'RTO-Out for Delivery\',\'RTO\') ,(\'RTO-Delivered\',\'RTO\') ,(\'OUT FOR PICKUP\',\'Pickup Error\') ,(\'RTO_NDR\',\'RTO\') ,(\'RTO-Exception\',\'Exception\') ,(\'Delayed\',\'In Transit\') ,(\'IN TRANSIT-AT SOURCE HUB\',\'In Transit\') ,(\'RTS\',\'Underprocess\') ,(\'Manifested\',\'Pickup Error\') ,(\'Dispatched\',\'In Transit\') ,(\'RTO\',\'RTO\') ,(\'Not Picked\',\'Pickup Error\') ,(\'DAMAGED\',\'Damaged\') ,(\'Closed\',\'Cancelled\') ,(\'Open\',\'Open\') ,(\'On Hold\',\'On Hold\') ,(\'Shipped - Returned to Seller\',\'RTO\') ,(\'Shipped - Delivered to Buyer\',\'Delivered\') ,(\'Shipped - Picked Up\',\'In Transit\') ,(\'Shipped - Rejected by Buyer\',\'RTO\') ,(\'Shopify_Processed\',\'Shopify_Processed\') ,(\'Ready to dispatch\',\'Ready to Dispatch\') ,(\'RTO Undelivered\',\'RTO\') ,(\'Shipment Lost\',\'Lost\') ,(\'Shipment Error\',\'Shipment Error\') ,(\'RTO In-Transit\',\'RTO\') ,(\'Dispatch / RTO\',\'RTO\') ,(\'Pending Pick-up\',\'Pending\') ,(\'Dispatch/Intransit\',\'In Transit\') ,(\'Dispatch /Lost and Damange\',\'Lost\') ,(\'Dispatch /Undelivered\',\'Undelivered\') ,(\'Non serviceable\',\'Non Serviceable\') ,(\'Not serviceable\',\'Non Serviceable\') ,(\'Dispatch/Delivered\',\'Delivered\') ,(\'Refund\',\'Refund\') ,(\'F&P\',\'F&P\') ,(\'SHIPPED - RETURNING TO SELLER\',\'RTO\') ,(\'SHIPPED - LOST IN TRANSIT\',\'Lost\') ,(\'SHIPPED - DAMAGED\',\'Damaged\') ,(\'SHIPPED - OUT FOR DELIVERY\',\'Out for delivery\'); CREATE OR REPLACE TABLE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_KWIKENGAGE_DAILY_REVENUE AS SELECT TO_DATE(\"DATE\") AS ORDER_DATE, \'KWIKENGAGE\' AS CHANNEL, UPPER(TRIM(BRAND)) AS BRAND, SUM(COALESCE(REVENUE, 0)) AS SELLING_PRICE FROM PEESAFE_DB.MAPLEMONK.PEE_SAFE_KWIKENGAGE_CAMPAIGN_REPORT GROUP BY TO_DATE(\"DATE\"), UPPER(TRIM(BRAND)); CREATE OR REPLACE TABLE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated_intermediate AS SELECT d.source AS source_system, b.customer_id, UPPER(b.SHOP_NAME) AS SHOP_NAME, UPPER(b.shop_name) AS marketplace, UPPER(b.FINAL_UTM_CHANNEL) AS CHANNEL, UPPER(b.FINAL_UTM_SOURCE) AS SOURCE, UPPER(b.FINAL_UTM_TYPE) AS TYPE, b.ORDER_ID, b.order_name AS reference_code, b.PHONE, b.NAME, b.EMAIL, COALESCE(b.shipping_status_update_date, c.shipping_last_update_date::datetime, d.shipping_last_update_date::datetime) AS SHIPPING_LAST_UPDATE_DATE, b.SKU, b.PRODUCT_ID, UPPER(b.PRODUCT_NAME) AS PRODUCT_NAME, b.CURRENCY, UPPER(b.CITY) AS CITY, UPPER(b.STATE) AS STATE, UPPER(b.ORDER_STATUS) AS ORDER_STATUS, b.ORDER_TIMESTAMP::DATE AS ORDER_DATE, b.ORDER_TIMESTAMP, b.QUANTITY, b.GROSS_SALES_BEFORE_TAX AS GROSS_SALES_BEFORE_TAX, b.DISCOUNT AS DISCOUNT, b.TAX, b.SHIPPING_PRICE, b.TOTAL_SALES AS SELLING_PRICE, UPPER(COALESCE(c.order_status, d.order_status)) AS OMS_ORDER_STATUS, UPPER(COALESCE(b.shipping_status, c.shipping_status, d.shipping_status)) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status, c.shipping_status, d.shipping_status)) AS FINAL_SHIPPING_STATUS, b.LINE_ITEM_ID::VARCHAR AS SALEORDERITEMCODE, d.sales_order_item_id AS SALES_ORDER_ITEM_ID, COALESCE(b.awb, c.awb, d.awb) AS AWB, UPPER(REPLACE(PARSE_JSON(GATEWAY)[0], \'\"\', \'\')) AS PAYMENT_GATEWAY, UPPER(COALESCE(c.payment_mode, d.payment_mode)) AS PAYMENT_MODE, UPPER(COALESCE(c.Courier, d.courier, b.courier)) AS COURIER, COALESCE(b.Shipping_created_at, c.manifest_date, d.dispatch_date) AS DISPATCH_DATE, COALESCE(c.delivered_date, d.delivered_date, CASE WHEN b.shipping_status LIKE \'delivered\' THEN b.shipping_status_update_date END) AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, b.shipping_status, c.shipping_status, d.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, COALESCE(CASE WHEN b.IS_REFUND = 1 AND LOWER(b.order_status) NOT IN (\'cancelled\') THEN 1 END, c.IS_REFUND, d.return_flag) AS RETURN_FLAG, CASE WHEN RETURN_FLAG = 1 AND LOWER(b.order_status) NOT IN (\'cancelled\') THEN IFNULL(refund_quantity, 0) END AS RETURNED_QUANTITY, CASE WHEN RETURN_FLAG = 1 AND LOWER(b.order_status) NOT IN (\'cancelled\') THEN IFNULL(refund_value, 0) END AS RETURNED_SALES, CASE WHEN LOWER(b.order_status) IN (\'cancelled\') THEN b.quantity::INT END AS CANCELLED_QUANTITY, b.shopify_new_customer_flag AS NEW_CUSTOMER_FLAG, UPPER(b.shopify_acquisition_product) AS ACQUISITION_PRODUCT, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, b.shipping_status, c.shipping_status, d.shipping_status)) IN (\'delivered\', \'delivered to origin\') THEN DATEDIFF(DAY, DATE(b.ORDER_TIMESTAMP), DATE(COALESCE(b.shipping_status_update_date, c.shipping_last_update_date::datetime, d.shipping_last_update_date::datetime))) WHEN LOWER(COALESCE(shipmap.final_shipping_status, b.shipping_status, c.shipping_status, d.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATEDIFF(DAY, DATE(b.ORDER_TIMESTAMP), GETDATE()) END::INT AS DAYS_IN_SHIPMENT, b.shopify_acquisition_date AS ACQUSITION_DATE, b.SKU_CODE, UPPER(b.PRODUCT_NAME_FINAL) AS PRODUCT_NAME_FINAL, UPPER(b.PRODUCT_CATEGORY) AS PRODUCT_CATEGORY, UPPER(b.PRODUCT_SUB_CATEGORY) AS PRODUCT_SUB_CATEGORY, UPPER(c.warehouse_name) AS WAREHOUSE, COALESCE(b.pincode, d.shipping_pincode, c.pincode) AS PINCODE, COALESCE(c.source_pincode, NULL) AS SOURCE_PINCODE, case when lower(b.shop_name) like \'%pee%\' then \'Pee Safe\' when lower(b.shop_name) like \'%furr%\' then \'Furr\' end as brand, TRY_TO_NUMBER(REPLACE(gs.\"Commission_Value on Sale\", \'%\', \'\')) / 100 * b.TOTAL_SALES AS AFFILIATE_COMMISSION FROM PEESAFE_DB.MAPLEMONK.PEESAFE_DB_SHOPIFY_FACT_ITEMS b LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY reference_code, Marketplace_LineItem_ID ORDER BY last_update_date DESC ) AS rw FROM PEESAFE_DB.MAPLEMONK.PEESAFE_DB_EasyEcom_FACT_ITEMS ) z WHERE z.rw = 1 AND LOWER(marketplace) LIKE ANY (\'%shopify%\') ) c ON REPLACE(b.order_name, \'#\', \'\') = c.reference_code AND b.LINE_ITEM_ID = c.Marketplace_LineItem_ID LEFT JOIN ( SELECT * FROM ( SELECT order_id, city, state, shipping_pincode, saleorderitemcode, sales_order_item_id, shippingpackagecode, SHIPPINGPACKAGESTATUS, shipping_status, order_status, Courier, Dispatch_Date, Delivered_date, Return_flag, Return_quantity, cancelled_quantity, shipping_last_update_date, awb, payment_method, PAYMENT_MODE, email, source, ROW_NUMBER() OVER ( PARTITION BY order_id, SPLIT_PART(saleorderitemcode, \'-\', 0) ORDER BY shipping_last_update_date DESC ) AS rw FROM PEESAFE_DB.MAPLEMONK.PEESAFE_DB_UNICOMMERCE_FACT_ITEMS WHERE LOWER(marketplace) LIKE ANY (\'%shopify%\') ) WHERE rw = 1 ) d ON b.order_id = d.order_id AND b.line_item_id = SPLIT_PART(d.saleorderitemcode, \'-\', 0) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER ( PARTITION BY LOWER(shipping_Status) ORDER BY 1 ) AS rw FROM PEESAFE_DB.MAPLEMONK.shipment_status_mapping ) WHERE rw = 1 ) ShipMap ON LOWER( COALESCE( b.shipping_status, c.shipping_status, d.shipping_status, b.ORDER_STATUS ) ) = LOWER(ShipMap.shipping_status) LEFT JOIN PEESAFE_DB.MAPLEMONK.PEE_SAFE_GS_AFFILIATE_COSTS gs ON UPPER(TRIM(b.final_utm_source)) = UPPER(TRIM(gs.\"Affiliate/ Source\")) ; create or replace table PEESAFE_DB.MAPLEMONK.Final_customerID as with new_phone_numbers as ( select phone, contact_num, 19700000000 + row_number() over( order by contact_num asc ) as maple_monk_id from ( select distinct right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'),10) as contact_num, phone from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated_intermediate ) a ), int as ( select contact_num, email, coalesce(maple_monk_id,id2) as maple_monk_id from ( select contact_num, email, maple_monk_id, 19800000000+row_number() over(partition by maple_monk_id is NULL order by email asc ) as id2 from ( select distinct coalesce(p.contact_num,right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10)) as contact_num, e.email, maple_monk_id from ( select phone as contact_num, email from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated_intermediate ) e left join new_phone_numbers p on p.contact_num = right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10) ) a ) b ) select contact_num, email, maple_monk_id from int where coalesce(contact_num,email) is not NULL; create or replace table PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated as select coalesce(m.maple_monk_id_phone, d.maple_monk_id) as customer_id_final, min(order_date) over(partition by customer_id_final) as acquisition_date, min(case when lower(order_status) not in (\'cancelled\') then order_date end) over(partition by customer_id_final) as first_complete_order_date, m.* from ( select c.maple_monk_id as maple_monk_id_phone, o.* from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated_intermediate o left join ( select * from ( select contact_num phone, maple_monk_id, row_number() over (partition by contact_num order by maple_monk_id asc) magic from PEESAFE_DB.MAPLEMONK.Final_customerID ) where magic =1 )c on c.phone = right(regexp_replace(o.phone, \'[^a-zA-Z0-9]+\'),10) )m left join ( select distinct maple_monk_id, email from PEESAFE_DB.MAPLEMONK.Final_customerID where contact_num is null )d on d.email = m.email; ALTER TABLE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated drop COLUMN new_customer_flag ; ALTER TABLE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated ADD COLUMN new_customer_flag varchar(50); ALTER TABLE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated ADD COLUMN new_customer_flag_month varchar(50); ALTER TABLE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated drop COLUMN acquisition_product ; ALTER TABLE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated ADD COLUMN acquisition_product varchar(16777216); ALTER TABLE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated ADD COLUMN acquisition_channel varchar(16777216); ALTER TABLE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated ADD COLUMN acquisition_marketplace varchar(16777216); UPDATE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date then \'New\' WHEN Order_Date < first_complete_order_date or first_complete_order_date is null THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date then \'Repeat\' END AS Flag FROM PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final; UPDATE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) in (\'cancelled\') end) THEN \'Yet to make completed order\' ELSE new_customer_flag END; UPDATE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Last_day(order_date, \'month\') = Last_day(first_complete_order_date, \'month\') THEN \'New\' WHEN Last_day(order_date, \'month\') < Last_day(first_complete_order_date, \'month\') or acquisition_date is null THEN \'Yet to make completed order\' WHEN Last_day(order_date, \'month\') > Last_day(first_complete_order_date, \'month\') THEN \'Repeat\' END AS Flag FROM PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final; UPDATE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' ELSE new_customer_flag_month END; CREATE OR replace temporary TABLE PEESAFE_DB.MAPLEMONK.temp_source_1 AS SELECT DISTINCT customer_id_final, channel, marketplace FROM ( SELECT DISTINCT customer_id_final, order_date, source as channel, shop_name as marketplace, Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate FROM PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated ) res WHERE order_date=firstorderdate; UPDATE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated AS a SET a.acquisition_channel=b.channel FROM PEESAFE_DB.MAPLEMONK.temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; UPDATE PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated AS a SET a.acquisition_marketplace=b.marketplace FROM PEESAFE_DB.MAPLEMONK.temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; DELETE FROM PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated WHERE UPPER(TRIM(CHANNEL)) = \'KWIKENGAGE\' AND SOURCE_SYSTEM = \'KWIKENGAGE_CAMPAIGN_REPORT\' AND ORDER_ID IS NULL; INSERT INTO PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated ( SOURCE_SYSTEM, SHOP_NAME, MARKETPLACE, CHANNEL, SOURCE, TYPE, ORDER_DATE, ORDER_TIMESTAMP, SELLING_PRICE, BRAND ) SELECT \'KWIKENGAGE_CAMPAIGN_REPORT\' AS SOURCE_SYSTEM, BRAND AS SHOP_NAME, BRAND AS MARKETPLACE, \'KWIKENGAGE\' AS CHANNEL, \'KWIKENGAGE\' AS SOURCE, \'CAMPAIGN\' AS TYPE, ORDER_DATE, ORDER_DATE::TIMESTAMP_NTZ AS ORDER_TIMESTAMP, SELLING_PRICE, BRAND FROM PEESAFE_DB.MAPLEMONK.PEESAFE_DB_KWIKENGAGE_DAILY_REVENUE; CREATE table if not exists PEESAFE_DB.MAPLEMONK.PEESAFE_DB_easyecom_returns_intermediate (ORDER_ID NUMBER,INVOICE_ID NUMBER,SUBORDER_ID VARIANT,REFERENCE_CODE VARCHAR,CREDIT_NOTE_ID NUMBER,ORDER_DATE TIMESTAMP_NTZ,INVOICE_DATE TIMESTAMP_NTZ,RETURN_DATE TIMESTAMP_NTZ,MANIFEST_DATE TIMESTAMP_NTZ,IMPORT_DATE TIMESTAMP_NTZ,LAST_UPDATE_DATE TIMESTAMP_NTZ,COMPANY_PRODUCT_ID VARIANT,PRODUCTNAME VARCHAR,PRODUCT_ID VARIANT,SKU VARCHAR,MARKETPLACE VARCHAR,MARKETPLACE_ID NUMBER,REPLACEMENT_ORDER NUMBER,RETURN_REASON VARCHAR,RETURNED_QUANTITY FLOAT,RETURN_AMOUNT_WITHOUT_TAX FLOAT,RETURN_TAX FLOAT,RETURN_SHIPPING_CHARGE FLOAT,RETURN_MISC FLOAT,TOTAL_RETURN_AMOUNT FLOAT) ; Create or replace table PEESAFE_DB.MAPLEMONK.PEESAFE_DB_easyecom_returns_fact_items as select ifnull(FE.Source,\'NA\') Marketing_CHANNEL ,FR.* from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_easyecom_returns_intermediate FR left join (select distinct replace(reference_code,\'#\',\'\') REFERENCE_CODE, Source from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated) FE on FR.REFERENCE_CODE = FE.REFERENCE_CODE; CREATE table if not exists PEESAFE_DB.MAPLEMONK.PEESAFE_DB_UNICOMMERCE_RETURNS_INTERMEDIATE ( MARKETPLACE VARCHAR ,SOURCE VARCHAR ,ORDER_ID VARCHAR ,REFERENCE_CODE VARCHAR ,PHONE VARCHAR ,NAME VARCHAR ,EMAIL VARCHAR ,ORDER_DATE TIMESTAMP_NTZ ,RETURN_DISPLAYCODE VARCHAR ,RETURN_STATUS VARCHAR ,INVENTORY_RECEIVED_DATE TIMESTAMP_NTZ ,RETURN_COMPLETE_DATE TIMESTAMP_NTZ ,RETURN_INVOICE_DISPLAY_CODE VARCHAR ,RETURN_COURIER VARCHAR ,RETURN_PROVIDER_SHIPPING_STATUS VARCHAR ,RETURN_TRACKING_NUMBER VARCHAR ,RETURN_TYPE VARCHAR ,SALEORDERITEMCODE VARCHAR ,ITEMSKU VARCHAR ,ITEM_NAME VARCHAR ,INVENTORY_TYPE VARCHAR ); create or replace table PEESAFE_DB.MAPLEMONK.PEESAFE_DB_unicommerce_returns_fact_items as select ifnull(FE.channel,\'NA\') Marketing_CHANNEL ,FE.quantity RETURNED_QUANTITY ,FE.selling_price as TOTAL_RETURN_AMOUNT ,FE.tax as RETURN_TAX ,FE.selling_price - FE.tax as RETURN_AMOUNT_WITHOUT_TAX ,FR.* from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_UNICOMMERCE_RETURNS_INTERMEDIATE FR left join (select replace(reference_code,\'#\',\'\') REFERENCE_CODE, SALEORDERITEMCODE, channel, Source, sum(quantity) quantity, sum(selling_price) Selling_price, sum(tax) tax from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_sales_consolidated group by 1,2,3,4) FE on FR.REFERENCE_CODE = FE.REFERENCE_CODE and FR.saleOrderItemCode = FE.SALEORDERITEMCODE; create or replace table PEESAFE_DB.MAPLEMONK.PEESAFE_DB_RETURNS_CONSOLIDATED as select upper(MARKETPLACE) Marketplace ,Return_Date ,upper(Marketing_CHANNEL) Marketing_channel ,sum(RETURNED_QUANTITY) TOTAL_RETURNED_QUANTITY ,sum(TOTAL_RETURN_AMOUNT) TOTAL_RETURN_AMOUNT ,sum(RETURN_TAX) TOTAL_RETURN_TAX ,sum(RETURN_AMOUNT_WITHOUT_TAX) TOTAL_RETURN_AMOUNT_EXCL_TAX from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_easyecom_returns_fact_items group by 1,2,3 union all select upper(MARKETPLACE) Marketplace ,RETURN_COMPLETE_DATE RETURN_DATE ,upper(Marketing_CHANNEL) Marketing_channel ,sum(RETURNED_QUANTITY) TOTAL_RETURNED_QUANTITY ,sum(TOTAL_RETURN_AMOUNT) TOTAL_RETURN_AMOUNT ,sum(RETURN_TAX) TOTAL_RETURN_TAX ,sum(RETURN_AMOUNT_WITHOUT_TAX) TOTAL_RETURN_AMOUNT_EXCL_TAX from PEESAFE_DB.MAPLEMONK.PEESAFE_DB_UNICOMMERCE_RETURNS_FACT_ITEMS group by 1,2,3;",
                    "transaction": true
                }
            ) }}
